package cryptosquare

import (
	"strings"
	"unicode"
)

// Encode normalizes the plaintext (removing spaces and punctuation and
// lower-casing it), organizes it into a rectangle as square as possible,
// and returns the columns of that rectangle, separated by spaces.
func Encode(pt string) string {
	var b strings.Builder
	for _, r := range pt {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			b.WriteRune(unicode.ToLower(r))
		}
	}
	s := b.String()
	n := len(s)
	if n == 0 {
		return ""
	}

	c := ceilSqrt(n)
	r := (n + c - 1) / c

	chunks := make([]string, c)
	for j := 0; j < c; j++ {
		var col strings.Builder
		col.Grow(r)
		for i := 0; i < r; i++ {
			idx := i*c + j
			if idx < n {
				col.WriteByte(s[idx])
			} else {
				col.WriteByte(' ')
			}
		}
		chunks[j] = col.String()
	}
	return strings.Join(chunks, " ")
}

// ceilSqrt returns the smallest integer c such that c*c >= n.
func ceilSqrt(n int) int {
	c := int(math.Round(math.Sqrt(float64(n))))
	// Adjust to guarantee c*c >= n
	for c*c < n {
		c++
	}
	for c > 0 && (c-1)*(c-1) >= n {
		c--
	}
	return c
}
```

